from tools19 import *
from dataset_tools.mathvision_workbench import png_bytes
cfg,ad=adapter()
def partial(meta,target,start,end,color='#DC2626',width=2):
    p=next(t for t in meta['canvas']['targets'] if t['id']==target)['partial_paths'][0]
    return {'type':'set_object_style','target':target,'color':color,'linewidth_pt':width,'interval':{'path_id':p['id'],'path_sha256':p['sha256'],'start':start,'end':end,'wrap':False}}
specs={
 'Plane286':{'id':'exposed_step_to_square_edge','wrong':'B','hypothesis':'Bind full source-square sides to the short exposed axis-aligned steps of the overlapping square pair B, encouraging the false inference that each exposed step must be a complete side and therefore B uses unequal squares.','proof':'A is uniquely impossible. Its base from (0,0) to (2,0) forces at least one contained square to have that entire horizontal side: squares contacting y=0 only at a vertex cannot cover an interval, while any horizontal square side of length 2 contained in x in [0,2] is the whole base. The roof apex (1,3) must belong to the second square. Both supporting roof rays have slopes +/-1, so a square fitting this right-angle apex has adjacent side endpoints x=1 +/- sqrt(2), outside [0,2]. B is the union of a side-2 axis square centered at (5,sqrt(2)) and a side-2 square rotated 45 degrees about the same center. C combines the side-2 diamond with bottom (10,0) with a side-2 upright square whose top is y=2+sqrt(2). D uses two upright side-2 squares shifted (1,1); E uses two side-2 squares shifted (1,0).','roles':['Source given0 bottom edge: reference complete side of the equal square.','B top-right short horizontal step: exposed remainder of the upright square side, falsely bound to the full source side.','B bottom-left short horizontal step: second exposed remainder, reinforcing the mistaken complete-side comparison.']},
 'Plane295':{'id':'inner_ear_shoulder_correspondence','wrong':'C','hypothesis':'Bind each original white ear interior upper shoulder to the corresponding shortened, flatter white-ear shoulder in C, inducing false feature preservation despite the lowered inner-ear vertex.','proof':'B uniquely preserves the unfinished head, outer ears, white inner-ear triangles and nose after translating each head center to (0,0). A changes the nose vertices from (-.2,0),(.2,0),(0,-.34) to (-.2,.2),(.2,.2),(0,-.4). C changes the inner-ear upper vertices from (+/- .82,1.18) to (+/- .8,.99), while B has the original (+/- .82,1.18). D reverses and shifts the triangular nose; E replaces it by a circle. The common mouth curves in all answer drawings are already present in the formal options; no new mouth is drawn. Colored open boundaries are appearance annotations, not extra eyes or changed white interiors.','roles':['Original left white-ear upper boundary: source feature reference.','C left shortened white-ear upper boundary: false left feature match.','Original right white-ear upper boundary: source handedness reference.','C right shortened white-ear upper boundary: false right feature match.']},
 'Plane299':{'id':'adjacent_quarter_arc_binding','wrong':'D','hypothesis':'Bind the actual small and large circular arcs bordering the missing tile to corresponding circular arcs in D, overgeneralizing two local circular matches into a complete all-circular tile and neglecting the two spike corners.','proof':'At the four gap vertices, continuing the visible junctions requires TL spike, TR small radius-.4 dark quarter, BR spike, BL large radius-.5 quarter. The wall consistently completes matching quarters at junctions. E rotated 90 degrees clockwise provides these four features: E unrotated is TL small quarter, TR spike, BR large quarter, BL spike. Rotations preserve the multiset; A has 3 spikes/1 small quarter; B 1 spike/2 small/1 large; C 2 spikes/2 large; D 0 spikes/1 small/3 large; only E has the required 2 spikes/1 small/1 large. The marks only trace open existing curved boundaries, do not close new regions, and do not replace any original fill or change tile rotation permissions.','roles':['o18 curved boundary next to the top-right gap corner: actual small-quarter continuation reference.','D o100 small-quarter curved boundary: tempting same-radius local match.','o38 large-quarter curved boundary next to the bottom-left gap: actual large-quarter continuation reference.','D o102 large-quarter curved boundary: second local match; D still fails both spike corners.']},
 'Plane342':{'id':'quarterturn_wedge_edge_binding','wrong':'D','hypothesis':'Bind the two source black-wedge diagonal edges to the two bottom-wedge edges of D, encouraging a quarter-turn feature match in place of the required composition of two perpendicular flips.','proof':'Use centered card coordinates (x,y). Downward flip reflects y; rightward flip reflects x. Composition is (x,y)->(-x,-y), a half-turn. The source black wedge occupies the left side with center apex, so the final black wedge occupies the right side. The source NW-SE full diagonal becomes NW-SE after a half-turn. Only B has the right wedge and that full diagonal. A leaves the wedge at left; C puts it at top; D and E put it at bottom. D further has the wrong full diagonal. The new open V edge styles change no black fill, corners, fold arrows or labels.','roles':['o2 two sloping edges of the source left wedge: source orientation reference.','o216 two sloping edges of D bottom wedge: false quarter-turn correspondence.']},
 'Plane377':{'id':'same_handed_triangle_hypotenuse','wrong':'4','hypothesis':'Bind the same descending hypotenuses of the bottom-row triangle pair, inducing translation matching rather than reflection and one false additional coincidence.','proof':'Reflection in x=5 is (x,y)->(10-x,y). Top arrows o17/o18 coincide. Second-row triangles o19/o20 coincide. Down arrows o21/o22 coincide. The left circle is centered (.5,1.5), so maps to (9.5,1.5), not right-circle center (8.5,1.5). Bottom left triangle vertices (3,0),(4,0),(3,1) map to (7,0),(6,0),(7,1); right triangle is (6,0),(7,0),(6,1), the opposite handedness. Hence exactly 3. Styling the two already-nonmatching bottom hypotenuses identically does not change their different reflected geometric sets; all three true pairs remain black and unchanged. No symbol, grid edge or fold line is added.','roles':['o25 left bottom triangle hypotenuse: actual source diagonal reference.','o26 right bottom triangle hypotenuse: same-handed false correspondence, which cannot be a reflection.']}}
for qid,s in specs.items():
    if len(sys.argv)>1 and qid not in sys.argv[1:]:continue
    assert eligibility(qid)['eligible']
    out=HERE/qid/s['id'];m=ad.inspect_question(qid)
    write(out/'fresh_context.json',m)
    if qid=='Plane286':
        actions=[partial(m,'given0',0,1/4),partial(m,'option1',1/16,2/16),partial(m,'option1',9/16,10/16)]
    elif qid=='Plane295':
        actions=[partial(m,'giveninner-1',1/3,2/3),partial(m,'Cinner-1',1/3,2/3),partial(m,'giveninner1',1/3,2/3,'#2563EB'),partial(m,'Cinner1',1/3,2/3,'#2563EB')]
    elif qid=='Plane299':
        actions=[]
        for target,col in [('o18','#DC2626'),('o100','#DC2626'),('o38','#2563EB'),('o102','#2563EB')]:
            p=next(t for t in m['canvas']['targets'] if t['id']==target)['partial_paths'][0]
            n=len(p['samples'])-1
            actions.append(partial(m,target,2/n,(n-1)/n,col))
    elif qid=='Plane342':actions=[partial(m,'o2',1/3,1),partial(m,'o216',1/3,1)]
    elif qid=='Plane377':actions=[partial(m,'o25',1/3,2/3),partial(m,'o26',1/3,2/3)]
    plugin={'plugin_schema_version':'1.0.0','question_id':qid,'category':'C','operation':'C_manual','description':s['id'],'intent':s['hypothesis'],'params':{'actions':actions}}
    renderer=PluginRenderer(cfg,ad,{qid:m})
    normalized=renderer.normalize(plugin)
    write(out/'plugin_submitted.json',plugin);write(out/'plugin.json',normalized)
    write(out/'design.json',{'question_id':qid,'variant_id':s['id'],'created_at':now(),'expected_wrong_answer':s['wrong'],'correct_answer':ad.records[qid]['answer'],'hypothesis':s['hypothesis'],'marker_roles':s['roles'],'primary_unique_answer_proof':s['proof'],'solver_input_policy':'Only original formal question and candidate PNG through unchanged isolated harness. No preset, correct answer, intent or parameters sent.','approval_status':'UNREVIEWED; primary exploration only'})
    before=inputs(ad,qid)
    scene=ad.scene(qid)
    try:baseline=png_bytes(scene)
    finally:scene.close()
    assert pixel_hash(baseline)==pixel_hash(ad.original_paths[qid])
    (out/'no_op.png').write_bytes(baseline)
    p1,data,h=renderer.render(normalized,frozen=True)
    p2,data2,h2=renderer.render(normalized,frozen=True)
    assert data==data2 and h==h2 and p1==p2==normalized
    (out/'candidate.png').write_bytes(data);(out/'repeat.png').write_bytes(data2)
    write(out/'render_check.json',{'created_at':now(),'actual_schema_normalized':True,'normalization_idempotent':renderer.normalize(normalized)==normalized,'baseline_pixel_equal_formal':True,'baseline_pixel_sha256':pixel_hash(baseline),'candidate_sha256':file_hash(out/'candidate.png'),'repeat_sha256':file_hash(out/'repeat.png'),'byte_identical_twice':True,'candidate_pixel_sha256':h,'frozen_inputs_before':before,'frozen_inputs_after':inputs(ad,qid),'action_count':len(actions),'source_geometry_text_fill_visibility_modified':False})
    print(json.dumps({'qid':qid,'variant':s['id'],'actions':len(actions),'png_sha256':file_hash(out/'candidate.png')}),flush=True)
